 (figs/'OPEN_RESULTS.html').write_text('<!doctype html><html lang="zh"><meta charset="utf-8"><title>LPS宏观标定与时间步审查</title><style>body{font:17px system-ui;max-width:1400px;margin:30px auto;padding:0 20px;color:#24323a;background:#f8fafb}section{background:white;padding:18px;margin:22px 0;border:1px solid #d7dfe3}img{width:100%;height:auto}h2{font-size:20px}a{color:#216591}</style><h1>LPS 宏观标定与时间步审查</h1><p>实现检查完成；G有限试样不匹配，材料Gc未识别；微泡内部轨迹敏感。具体dt/dx结论见报告。</p><p><a href="'+reportrel+'">完整评审</a> · <a href="'+csvrel+'">MACRO_TEST_RESULTS.csv</a></p>'+cards+'</html>')
 # Hash native/raw data in place; never pull large files just to hash them.
 manifest={}
 for p in sorted(base.rglob('*')):
  if p.is_file() and p.name not in ['FILE_MANIFEST.json']:
   h=hashlib.sha256()
   with p.open('rb') as f:
    for block in iter(lambda:f.read(8*1024*1024),b''):h.update(block)
   manifest[str(p.relative_to(base))]=dict(bytes=p.stat().st_size,sha256=h.hexdigest())
 save(base/'FILE_MANIFEST.json',dict(server_root=str(base),files=manifest,total_bytes=sum(x['bytes'] for x in manifest.values()),scope='Before WSL document update; final document/update receipts have their own hashes'))
 print(json.dumps(status,ensure_ascii=False,indent=2))
